INSERT INTO `notify` (`id`, `name`, `text`) VALUES
(1, 'Hỗ trợ nhiệm vụ', '1) Hỗ trợ nhiệm vụ TĐST:\r\nNgày thứ 2-3-4 trong tuần từ 5h\r\nđến 7h và từ 17h đến hết 19h,\r\nchỉ những cư dân đang làm nhiệm\r\nvụ này mới vào được map có boss,\r\nnày xuất hiện.\r\n(Núi khỉ đen, hang khỉ đen, núi khỉ\r\nđỏ).\r\n\r\n2) Hỗ trợ nhiệm vụ Xên Bọ Hung:\r\nNgày thứ 2-3-4 trong tuần, từ 2 giờ\r\nsáng đén hết 4 giờ sáng và từ 2 giờ\r\nchiều đến hết 4 giờ chiều, chỉ\r\nnhững cư dân đang làm nhiệm vụ\r\nnày mới vào được map có boss này\r\nxuất hiện.\r\n(Thị trấn Ginder, Võ đài Xên bọ\r\nhung).'),
(2, 'Quà tân thủ ', 'Tặng anh em tân thủ 50k VND '),
(3, 'Thông báo từ admin', '\r\n---> Có lỗi báo ngay Admin ( key vàng Tiến Vinh ) '),
(4, 'Tân Thủ ', '1) Loại tiền tệ trong game\r\n\r\n- Vàng : nhận từ npc nhiệm vụ , giết quái hoặc đổi từ thỏi vàng !\r\n- Ngọc xanh : nhận từ npc nhiệm vụ hoặc đổi từ VNĐ !\r\n- Ngọc hồng : nhận từ npc nhhiệm vụ hoặc đổi từ VNĐ !\r\n\r\n2) Loại đệ tử \r\n\r\n- Đệ thường : săn được từ Supper Broly ( khi giết broly sẽ có tỷ lệ sinh ra supper broly )\r\n- Đệ mabư : Nhặt quả trứng khi đánh bại boss Hirudegarn ( mở trứng để có đệ mabư )\r\n- Đệ mabư nhí : Giết boss mabư 12h và 14h có cơ hội nhận được trứng sơ sinh hoặc mua bằng vnđ\r\n- Đệ Cell nhí : Giết boss Siêu Bọ Hung tại võ đài có cơ hội nhận được trứng sơ sinh hoặc mua bằng vnđ\r\n- Đệ Fide nhí : Giết boss Fide tại núi khỉ vàng có cơ hội nhận được trứng sơ sinh hoặc mua bằng vnđ\r\n\r\n3) Loại Vật phẩm \r\n\r\n- Cỏ 4 lá : vật phẩm may mắn tăng x2 cơ hội \r\n- Ngọc rồng : ngọc rồng 5-7sao kiếm được từ việc đánh quái , boss , làm nhiệm vụ !\r\n- Đá nâng cấp : nâng cấp từ mảnh đá vụn ở npc bà hạt mít !\r\n- Mảnh đá vụn : đánh quái có tỷ lệ rớt !\r\n- Sao pha lê : cho sói hẹc quyn ăn xương !\r\n- Capsule kì bí : làm đến nhiệm vụ yêu cầu đến bulma ở tương lai mua máy dò ( đánh quái )\r\n- Mảnh vỡ bông tai : tìm giu-ma đầu bò để đến map up \r\n\r\n4) Sét Kích Hoạt thường và vip\r\n\r\n- Dùng cỏ 4 lá giúp tăng tỉ lệ \r\n- Đầy đủ sét kích hoạt teamobi có hiện tại\r\n- Đồ sẽ xuất hiện 3 map tính từ làng !\r\n- Ở bà hạt mít 2 món thần linh 1 món hủy diệt hình thức lấy đồ hủy diệt làm món đồ ra tiếp theo\r\n(đồ cùng hành tinh nếu đồ khác hành tinh món đồ ra cũng sẽ khác thì sẽ ra cùng hành tinh)\r\n \r\n5) Đồ 3 sao \r\n\r\n- Đánh quái có tỷ lệ rơi ra đồ sao ngẫu nhiên 1-3 sao\r\n- Đồ rớt ra có tỷ lệ không phải đồ vải thô !\r\n\r\n6) Đồ thần linh \r\n\r\n- Đánh quái có tỷ lệ rớt đồ thần linh !\r\n- Giết boss có tỷ lệ rớt đồ thần linh !\r\n- Nếu thừa đồ thần linh không dùng đến có thể đổi VNĐ\r\n\r\n7) Đồ hủy diệt \r\n\r\n- Khi mặc đồ thần linh đánh quái có tỷ lệ ra thức ăn \r\n- Thức ăn dùng để đổi đồ hủy diệt theo tỷ lệ NPC \r\n\r\n8) Đồ thiên sứ \r\n\r\n- Mảnh áo, quần, giày, găng, rada up tại hành tinh ngục tù ! \r\n- Mảnh áo, quần, giày, găng, rada gặp whis để ghép đồ !\r\n\r\n9) Chân mệnh thiên tử \r\n\r\n- Map địa ngục tại NPC bà hạt mít ở đảo kame\r\n- giết 3 con sói để nhận chân mệnh và nâng cấp nó !\r\n\r\n10) Cập nhật thêm '),
(5, 'Code', 'zinzin\r\nzinzin1\r\nzinzin2\r\nzinzin3\r\nzinzin4\r\nzinzin5\r\nzinzin6\r\n');
